// Закрываем по крестику - ищем кнопку в заголовке модального окна
cy.get('#modals').within(function () {
    cy.get('button').first().click();
});
// Проверяем, что модальное окно закрылось
cy.contains('Детали ингредиента').should('not.exist');

// Открываем модальное окно
cy.contains('Краторная булка N-200i').click();
cy.contains('Детали ингредиента').should('be.visible');
// Кликаем на оверлей - используем реальный DOM селектор
cy.get('#modals').then(function ($modals) {
    // Ищем первый div с position: fixed (это overlay)
    var overlay = $modals.find('div').filter(function (_, el) {
        var style = window.getComputedStyle(el);
        return style.position === 'fixed';
    }).first();
    if (overlay.length > 0) {
        cy.wrap(overlay).click({ force: true });
    }
    else {
        // Если overlay не найден, используем клик по координатам
        cy.get('body').click(100, 100, { force: true });
    }
});
// Проверяем, что модальное окно закрылось
cy.contains('Детали ингредиента').should('not.exist');

